class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        def build(par):
            c = [0] * k
            for i in range(par, len(nums), 2):
                c[nums[i] % k] += 1
            return c
        def costs(c):
            res = []
            for x in range(k):
                s = 0
                for r in range(k):
                    if c[r]:
                        d = abs(x - r)
                        s += c[r] * min(d, k - d)
                res.append(s)
            return res
        ce = costs(build(0))
        co = costs(build(1))
        order = sorted(range(k), key=lambda i: co[i])
        b1, b2 = order[0], order[1]
        return min(v + (co[b1] if i != b1 else co[b2]) for i, v in enumerate(ce))

