class Solution {
public:
    long long minOperations(vector<int>& nums, int k) {
        auto build = [&](int par) {
            vector<long long> c(k, 0);
            for (int i = par; i < (int)nums.size(); i += 2) c[nums[i] % k]++;
            return c;
        };
        auto costs = [&](vector<long long>& c) {
            vector<long long> res(k);
            for (int x = 0; x < k; x++) {
                long long s = 0;
                for (int r = 0; r < k; r++)
                    if (c[r]) { long long d = abs(x - r); s += c[r] * min(d, (long long)k - d); }
                res[x] = s;
            }
            return res;
        };
        auto ce = costs(build(0));
        auto co = costs(build(1));
        int b1 = 0, b2 = -1;
        for (int i = 1; i < k; i++) {
            if (co[i] < co[b1]) { b2 = b1; b1 = i; }
            else if (b2 == -1 || co[i] < co[b2]) b2 = i;
        }
        long long ans = LLONG_MAX;
        for (int x = 0; x < k; x++)
            ans = min(ans, ce[x] + (x == b1 ? co[b2] : co[b1]));
        return ans;
    }
};

