class Solution {
    public long minOperations(int[] nums, int k) {
        long[] ce = costs(hist(nums, k, 0), k);
        long[] co = costs(hist(nums, k, 1), k);
        int b1 = 0, b2 = -1;
        for (int i = 1; i < k; i++) {
            if (co[i] < co[b1]) { b2 = b1; b1 = i; }
            else if (b2 == -1 || co[i] < co[b2]) b2 = i;
        }
        long ans = Long.MAX_VALUE;
        for (int x = 0; x < k; x++)
            ans = Math.min(ans, ce[x] + (x == b1 ? co[b2] : co[b1]));
        return ans;
    }
    private long[] hist(int[] nums, int k, int par) {
        long[] c = new long[k];
        for (int i = par; i < nums.length; i += 2) c[nums[i] % k]++;
        return c;
    }
    private long[] costs(long[] c, int k) {
        long[] res = new long[k];
        for (int x = 0; x < k; x++) {
            long s = 0;
            for (int r = 0; r < k; r++)
                if (c[r] > 0) { long d = Math.abs(x - r); s += c[r] * Math.min(d, k - d); }
            res[x] = s;
        }
        return res;
    }
}

