class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        def costs(par):
            cnt = [0] * k
            for i in range(par, len(nums), 2):
                cnt[nums[i] % k] += 1
            P = [0] * (k + 2)
            Q = [0] * (k + 2)
            for r in range(k):
                P[r + 1] = P[r] + cnt[r]
                Q[r + 1] = Q[r] + cnt[r] * r
            pt, qt = P[k], Q[k]
            h = k // 2
            res = []
            for x in range(k):
                lin = x * P[x] - Q[x] + (qt - Q[x + 1]) - x * (pt - P[x + 1])
                li = max(x - h, 0)
                ri = min(x + h + 1, k)
                pl, ql = P[li], Q[li]
                cr = pt - P[ri]
                qr = qt - Q[ri]
                wl = 2 * x * pl - 2 * ql - k * pl
                wr = 2 * (qr - x * cr) - k * cr
                res.append(lin - wl - wr)
            return res
        ce = costs(0)
        co = costs(1)
        b1, b2 = 0, 1
        if co[1] < co[0]:
            b1, b2 = 1, 0
        for i in range(2, k):
            if co[i] < co[b1]:
                b2, b1 = b1, i
            elif co[i] < co[b2]:
                b2 = i
        return min(v + (co[b1] if i != b1 else co[b2]) for i, v in enumerate(ce))

