            vector<long long> cnt(k, 0);
            for (int i = par; i < (int)nums.size(); i += 2) cnt[nums[i] % k]++;
            vector<long long> P(k + 2, 0), Q(k + 2, 0);
            for (int r = 0; r < k; r++) { P[r + 1] = P[r] + cnt[r]; Q[r + 1] = Q[r] + cnt[r] * r; }
            long long pt = P[k], qt = Q[k];
            int h = k / 2;
            vector<long long> res(k);
            for (int x = 0; x < k; x++) {
                long long lin = x * P[x] - Q[x] + (qt - Q[x + 1]) - x * (pt - P[x + 1]);
                int li = max(x - h, 0), ri = min(x + h + 1, k);
                long long pl = P[li], ql = Q[li];
                long long cr = pt - P[ri], qr = qt - Q[ri];
                long long wl = 2LL * x * pl - 2 * ql - (long long)k * pl;
                long long wr = 2 * (qr - x * cr) - (long long)k * cr;
                res[x] = lin - wl - wr;
            }
            return res;
        };
        auto ce = costs(0), co = costs(1);
        int b1 = 0, b2 = 1;
        if (co[1] < co[0]) swap(b1, b2);
        for (int i = 2; i < k; i++) {
            if (co[i] < co[b1]) { b2 = b1; b1 = i; }
            else if (co[i] < co[b2]) b2 = i;
        }
        long long ans = LLONG_MAX;
        for (int x = 0; x < k; x++)
            ans = min(ans, ce[x] + (x == b1 ? co[b2] : co[b1]));
        return ans;
    }
};

